"""Build a dependency-free submission from accepted Stage03 evidence only."""
import json, html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'submission/history/stage04-composio-assessment-uday.html'
FIELDS=['auth_methods','access_model','api_available','api_types','mcp_available','buildability','primary_blocker']
def read(name): return json.loads((ROOT/'data/stage03'/name).read_text(encoding='utf-8'))
def esc(v): return html.escape(', '.join(v) if isinstance(v,list) else str(v))
def build():
 rows=read('verified-results.json'); claims=read('claim-verification.json'); patterns=read('pattern-evidence.json')['insights']; reviews=read('human-review.json')
 compact=[]
 for r in rows:
  n=sum(c['status']=='checked' for c in claims if c['app_id']==r['id'] and c['field'] in FIELDS)
  compact.append({k:r[k] for k in ['id','app_name','category']+FIELDS}|{'checked':n})
 finding_titles=['Permissions shape onboarding','OAuth lifecycle is reusable','REST is a common foundation','MCP adds an execution surface','Buildability has conditions']
 findings=''.join('<article><span class="eyebrow">%s/%s resolved sampled claims</span><h3>%s</h3><p>%s</p><small>%s reviewed · %s unclear. %s</small></article>'%(p['numerator'],p['denominator'],title,esc(p['conclusion']),p['reviewed_denominator'],p['unclear_claims'],esc(p['caveat'])) for p,title in zip(patterns,finding_titles))
 examples=[]
 for name,field,lesson in [('Shopify','auth_methods','Separate token acquisition from token transport; permissions and review still condition distribution.'),('Cloudflare','auth_methods','Bearer transport alone misses OAuth2 and legacy API-key paths.'),('SE Ranking','mcp_available','An unknown can become a documented official hosted MCP surface.'),('HubSpot','access_model','Admin permission is an onboarding gate, distinct from pricing.'),('Paygent Connect','api_types','Identity must match before another product’s documentation can support a claim.')]:
  r=next(r for r in reviews if r['app_name']==name and r['field']==field)
  url=r.get('observed_source_url') or 'https://paygent.io/'
  examples.append('<tr><th scope="row">%s</th><td>%s</td><td><a href="%s">Official source inspected</a><br>%s</td><td>%s</td><td>%s</td></tr>'%(esc(name),esc(r['first_pass_value']),esc(url),esc((r.get('notes') or r.get('correction_reason') or '')[:260])+'…',esc(r['final_value']),esc(lesson)))
 content=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Integration readiness — Uday’s Composio assessment</title><style>
:root{--paper:#f8f7f2;--ink:#202b28;--muted:#58645e;--green:#275947;--line:#d6dbd3}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:32px 38px}a{color:var(--green);text-underline-offset:4px}header{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:16px;font-size:13px}nav{display:flex;gap:18px;flex-wrap:wrap}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.1em;color:var(--green);font-weight:700}h1{font:normal clamp(36px,5vw,64px)/1.08 Georgia,serif;max-width:900px;margin:20px 0}h2{font:normal 32px/1.2 Georgia,serif;margin:0 0 18px}h3{font-size:19px;line-height:1.3}p{margin:10px 0}small{font-size:13px;color:var(--muted)}.lead{max-width:860px;font-size:19px;color:var(--muted)}.hero{padding:46px 0 30px}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:20px;border-top:1px solid var(--line);padding:24px 0 0;margin-top:28px}.metrics b{display:block;font-size:25px;line-height:1.3}.metrics span{font-size:12px;color:var(--muted)}section{padding:38px 0;border-top:1px solid var(--line);scroll-margin-top:20px}.findings{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.findings article{border-top:3px solid var(--green);padding-top:12px}.flow{display:flex;flex-wrap:wrap;gap:10px;list-style:none;padding:0}.flow li{padding:8px 12px;background:#e6ece4;font-size:13px}.flow li:not(:last-child):after{content:' →';color:var(--green)}.two{display:grid;grid-template-columns:1fr 1fr;gap:32px}.score{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px;background:#e6ece4;padding:24px}.score b{font-size:38px;display:block}.bar{height:8px;background:#c8d3c6;margin:12px 0}.bar i{display:block;height:100%;background:var(--green)}.notice{border-left:4px solid var(--green);padding:10px 18px;background:#eef0e9}.scroll{overflow:auto;border:1px solid var(--line);margin-top:16px}table{border-collapse:collapse;width:100%;font-size:13px;line-height:1.5}th,td{padding:12px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}thead{background:#e6ece4}#matrix{min-width:1250px}#matrix th:first-child{min-width:150px}td.unknown{color:var(--muted);font-style:italic}.controls{display:flex;gap:12px;flex-wrap:wrap}.controls label{font-size:13px;display:flex;flex-direction:column;gap:4px}input,select{font:inherit;padding:10px;border:1px solid #829487;border-radius:3px;background:white;color:var(--ink)}input{min-width:250px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#e6ece4;padding:20px;font-size:13px}li{margin:6px 0}footer{padding:20px 0;font-size:12px;color:var(--muted)}:focus-visible{outline:3px solid #b77729;outline-offset:3px}@media(max-width:700px){main{padding:20px}.hero{padding-top:28px}.metrics{grid-template-columns:repeat(2,1fr)}.findings,.two{grid-template-columns:1fr}.score{gap:10px;padding:16px}.score b{font-size:27px}header{gap:20px;align-items:start;flex-direction:column}.controls label,input,select{width:100%}h2{font-size:28px}}@media print{.controls,nav{display:none}.scroll{overflow:visible}main{max-width:none}}
</style></head><body><main><header><strong>UDAY / COMPOSIO PRODUCT INTERN ASSESSMENT</strong><nav aria-label="Sections"><a href="#findings">Findings</a><a href="#verification">Verification</a><a href="#apps">100 apps</a><a href="#proof">Proof</a></nav></header>
<div class="hero"><span class="eyebrow">100 apps · 10 categories · evidence before certainty</span><h1>Integration readiness goes beyond the API.</h1><p class="lead">Researching 100 apps showed that integration readiness is less about whether an API exists and more about permissions, authentication, evidence quality, and verification. Human review improved the sampled claims; most dataset claims remain unresolved.</p><div class="metrics"><div><b>100</b><span>apps researched</span></div><div><b>10</b><span>categories</span></div><div><b>40</b><span>human-reviewed claims</span></div><div><b>7/35 → 35/35</b><span>same scoreable sample</span></div><div><b>5</b><span>sample claims unresolved</span></div><div><b>44/700</b><span>critical claims independently checked</span></div></div></div>
<section id="findings"><span class="eyebrow">01 / Findings</span><h2>Design the connector around the gates.</h2><p>These are bounded findings from the reviewed subset, not prevalence estimates for all 100 apps.</p><div class="findings">@@FINDINGS@@</div></section>
<section id="workflow"><span class="eyebrow">02 / Research agent</span><h2>A pipeline with a human boundary.</h2><ol class="flow">@@FLOW@@</ol><div class="two"><p>The Python pipeline used a structured schema and OpenAI strict JSON-schema extraction, preferred official sources, and checked evidence support. The initial discovery path fell back to assigned seed documentation after Composio authentication failed. Failed extraction produced explicit unknowns, rather than guessed capabilities.</p><p>First-pass runs were frozen. A deterministic sample (seed 42) selected 20 apps and 40 claims before judgments. Human review confirmed source identity and claim support; corrections were logged separately. A conservative verified projection then supported bounded pattern analysis.</p></div></section>
<section id="composio"><span class="eyebrow">03 / Composio contribution</span><h2>Live search augmented the research.</h2><p>The initial authentication failed because the wrong key type was used. After using a valid Composio Platform Project API key, live toolkit inspection selected <code>composio_search</code> and action <code>COMPOSIO_SEARCH_TAVILY</code>, observed version <code>20260903_00</code>.</p><p><strong>Eight successful live searches</strong> ran in a separate augmentation checkpoint. It preserved the frozen first pass. This was a separate research path; it does not establish that all 100 apps were researched through Composio.</p></section>
<section id="verification"><span class="eyebrow">04 / Verification</span><h2>The sample improved. Coverage stayed explicit.</h2><div class="score"><div><small>FIRST PASS</small><b>7/35</b><div class="bar"><i style="width:20%"></i></div>20% correct</div><div><small>AFTER VERIFICATION</small><b>35/35</b><div class="bar"><i style="width:100%"></i></div>100% on scoreable sample</div><div><small>UNCLEAR / UNSCORED</small><b>5</b>of 40 reviewed claims</div></div><p>On a deterministic 40-claim human sample, 35 claims were scoreable. The first pass matched 7/35; after source-backed human verification, the final values matched 35/35 of those same scoreable claims. Five claims remained unresolved.</p><p class="notice">This is a sample-level workflow result (+80 percentage points), not whole-dataset accuracy. Final judgments were supplied during verification, not via an independent delayed re-audit. Most first-pass misses were missing/unknown information: 25 unknown values later resolved and three incorrect or incomplete known values.</p><p>20 human-reviewed apps · 40 claims · 35 scoreable · 5 unscored · 0 pending. Unresolved: Freshdesk MCP; fanbasis access pricing tier; Harvest MCP; Paygent Connect API type and MCP.</p></section>
<section id="corrections"><span class="eyebrow">05 / Corrections</span><h2>What changed, and why it matters.</h2><div class="scroll"><table><caption>First pass → official evidence → verified result → lesson</caption><thead><tr><th>App</th><th>First pass</th><th>Evidence found</th><th>Verified result</th><th>Lesson</th></tr></thead><tbody>@@EXAMPLES@@</tbody></table></div></section>
<section id="failures"><span class="eyebrow">06 / Failure modes</span><h2>Gaps became review work, not hidden certainty.</h2><div class="scroll"><table><thead><tr><th>Failure mode</th><th>Detection</th><th>Mitigation</th></tr></thead><tbody><tr><th>Unknown first-pass claims</th><td>Paired human source review</td><td>Resolve supported values; retain unresolved unknowns.</td></tr><tr><th>Incomplete authentication classification</th><td>Official OAuth/token documentation</td><td>Use multi-label auth and distinguish acquisition from transport.</td></tr><tr><th>Pricing confused with permissions</th><td>Admin requirements and plan-tier review</td><td>Separate onboarding gates; abstain where pricing is unstated.</td></tr><tr><th>Irrelevant supporting quotation</th><td>Claim-level support review (HubSpot MCP)</td><td>Replace active evidence with official MCP documentation; preserve baseline.</td></tr><tr><th>Website login confused with developer API authentication</th><td>Vercel augmentation source inspection</td><td>Do not promote sign-in inference; use official REST token evidence.</td></tr><tr><th>Extraction failure</th><td>Frozen failure log (SendGrid)</td><td>Keep unknown record; augmentation remains a candidate until verified.</td></tr><tr><th>Product identity collision</th><td>Paygent identity review</td><td>Keep assigned identity; do not borrow another product’s docs.</td></tr></tbody></table></div><p><small>Archived extraction warnings are quality flags, not confirmed semantic errors. Coverage abstentions are not proven errors.</small></p></section>
<section id="apps"><span class="eyebrow">07 / Verified projection</span><h2>The full 100-app matrix.</h2><p>22 apps partially resolved · 78 apps with all seven critical fields unresolved · 0 fully verified rows. Unknown means unresolved; it does not mean blocked, no API, or no MCP. Coverage counts seven critical fields; primary blocker is shown separately.</p><div class="controls"><label>Search apps or claims<input id="search" type="search" placeholder="Try Shopify or OAuth2"></label><label>Category<select id="category"><option value="">All categories</option>@@OPTIONS@@</select></label><label>Coverage<select id="coverage"><option value="">All coverage states</option><option value="partial">Partially resolved</option><option value="unknown">All critical fields unresolved</option></select></label></div><p id="count" role="status" aria-live="polite">100 of 100 apps</p><div class="scroll" tabindex="0" aria-label="App matrix, scroll horizontally for all fields"><table id="matrix"><caption>Stage03 verified-only values. No app row is fully verified.</caption><thead><tr><th>App</th><th>Category</th><th>Auth</th><th>Access</th><th>API available</th><th>API type</th><th>MCP</th><th>Buildability</th><th>Primary blocker</th><th>Verification / coverage</th></tr></thead><tbody>@@ROWS@@</tbody></table></div><noscript>All 100 rows remain visible. Enable JavaScript for search and filters.</noscript></section>
<section id="proof"><span class="eyebrow">08 / Proof &amp; reproducibility</span><h2>Inspect the work behind the page.</h2><p><a href="https://github.com/udaySuryaP/composio-research-assessment">udaySuryaP/composio-research-assessment</a> · Stage04 branch: <code>stage04/case-study-submission</code></p><pre>python -B -m agent.stage03_finalize check
python -B -m unittest discover -s tests -v
python -B -m agent.stage04 build
python -B -m agent.stage04 check
# PowerShell: open the standalone artifact
Start-Process .\submission\composio-assessment-uday.html</pre><p>The immutable Stage02 run lives under <code>data/runs/stage02-full-fallback-20260916/</code>; Composio augmentation is separate. Stage03’s <code>human-review.json</code>, <code>correction-log.json</code>, <code>claim-verification.json</code>, <code>targeted-source-excerpts.json</code>, and <code>pattern-evidence.json</code> retain inspectable provenance. The verified projection is generated separately from the frozen first pass. Stage04 embeds only that accepted projection.</p></section>
<section id="limitations"><span class="eyebrow">09 / Limits of this evidence</span><h2>Uncertainty is part of the result.</h2><ul><li>Only 44/700 critical claims independently checked; 656/700 remain unresolved. The majority of the 100-app dataset remains unverified at claim level.</li><li>No app row is fully verified: 22 partially resolved, 78 entirely unresolved across seven critical fields.</li><li>API breadth is unknown for all 100 apps.</li><li>Five sampled claims remain unclear; no pending sample claims.</li><li>No live integrations were executed end-to-end. Documented buildability is not integration-test proof.</li><li>Category ranking is unsupported; reviewed-subset patterns cannot establish population prevalence.</li><li>Final verified judgments were supplied during verification and were not independently re-audited later.</li></ul></section><footer>Uday · Stage04 submission artifact · Accepted Stage01–03 evidence preserved · Opens locally without a build or network connection.</footer></main><script id="matrix-data" type="application/json">@@DATA@@</script><script>
const data=JSON.parse(document.getElementById('matrix-data').textContent);
function matches(r,q,category,coverage){return (!q||JSON.stringify(r).toLowerCase().includes(q.toLowerCase()))&&(!category||r.category===category)&&(!coverage||(coverage==='partial'?r.checked>0:r.checked===0));}
function filter(){const q=document.getElementById('search').value,cat=document.getElementById('category').value,cov=document.getElementById('coverage').value;let n=0;document.querySelectorAll('#matrix tbody tr').forEach((row,i)=>{row.hidden=!matches(data[i],q,cat,cov);if(!row.hidden)n++;});document.getElementById('count').textContent=n+' of 100 apps';}
['search','category','coverage'].forEach(id=>document.getElementById(id).addEventListener(id==='search'?'input':'change',filter));
</script></body></html>'''
 # Critical coverage uses the accepted seven-field rubric, including breadth, not primary blocker.
 from agent.stage03 import FIELDS as critical
 for r in compact: r['checked']=sum(c['status']=='checked' for c in claims if c['app_id']==r['id'] and c['field'] in critical)
 # Rebuild coverage cell after applying the canonical rubric.
 trs=''.join('<tr data-id="%s"><th scope="row">%s</th><td>%s</td>%s<td>%s / 7 checked · %s</td></tr>'%(r['id'],esc(r['app_name']),esc(r['category']),''.join('<td class="%s">%s</td>'%('unknown' if r[f]=='unknown' or r[f]==['unknown'] else '',esc(r[f])) for f in FIELDS),r['checked'],'partially resolved' if r['checked'] else 'unresolved') for r in compact)
 replacements={'FINDINGS':findings,'FLOW':''.join('<li>'+s+'</li>' for s in ['Assigned apps','Discovery','Official-source retrieval','Structured extraction','Evidence checks','Deterministic sample','Human verification','Correction log','Verified projection','Pattern analysis']),'EXAMPLES':''.join(examples),'ROWS':trs,'OPTIONS':''.join('<option>'+esc(c)+'</option>' for c in sorted({r['category'] for r in rows})),'DATA':json.dumps(compact,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c')}
 for k,v in replacements.items(): content=content.replace('@@'+k+'@@',v)
 OUT.parent.mkdir(exist_ok=True);OUT.write_text(content,encoding='utf-8');return content

def check():
 import re,subprocess
 from agent.stage03 import FIELDS as critical
 text=OUT.read_text(encoding='utf-8'); data=json.loads(re.search(r'<script id="matrix-data" type="application/json">(.*?)</script>',text,re.S).group(1)); rows=read('verified-results.json');claims=read('claim-verification.json')
 assert 0<OUT.stat().st_size<10_000_000
 assert len(data)==len({r['id'] for r in data})==len({r['app_name'] for r in data})==100
 assert len(re.findall(r'<tr data-id=',text))==100
 for a,b in zip(data,rows):
  assert all(a[k]==b[k] for k in ['id','app_name','category']+FIELDS)
  assert a['checked']==sum(c['status']=='checked' for c in claims if c['app_id']==a['id'] and c['field'] in critical)
 assert '<b>40</b><span>human-reviewed claims</span>' in text
 assert '<b>7/35 → 35/35</b><span>same scoreable sample</span>' in text
 assert '<b>5</b><span>sample claims unresolved</span>' in text
 assert '<b>44/700</b><span>critical claims independently checked</span>' in text
 assert '35 scoreable · 5 unscored · 0 pending' in text
 assert '656/700 remain unresolved' in text
 assert '0 fully verified rows' in text
 assert sum(r['checked'] for r in data)==44
 assert sum(r['checked']>0 for r in data)==22
 assert all(r['checked']<7 for r in data)
 assert all(r['api_breadth']=='unknown' for r in rows)
 for s in ['40','35','5','7/35','35/35','44/700','656/700','0 fully verified','https://github.com/udaySuryaP/composio-research-assessment','25 unknown','three incorrect','20 human-reviewed','0 pending','seed 42']: assert s in text,s
 for s in ['the dataset is now 100% accurate','all 100 apps were verified','verification achieved 100% accuracy across the dataset','35/35 proves full research correctness']: assert s not in text.lower()
 assert not re.search(r'fetch\s*\(|XMLHttpRequest|<script[^>]+src=|<link[^>]+href=',text)
 before=OUT.read_bytes();build();assert before==OUT.read_bytes(),'Artifact must match deterministic generator'
 changed=subprocess.check_output(['git','diff','a94cce23a4fbdaf9e8b80c03fa8e482f9057f73f','--name-only'],cwd=ROOT,text=True).splitlines()
 assert not subprocess.check_output(['git','diff','83bd643b087da28d2e1ed1439e381b3a8a9bca7f','--','data/runs','data/stage03','site','STAGE01.md','STAGE02.md','STAGE03.md','STAGE04.md'],cwd=ROOT),'Historical evidence changed'
 print(json.dumps({'stage04':'PASS','bytes':OUT.stat().st_size,'rows':100,'unique_apps':100,'checked':44,'unresolved':656,'partially_resolved':22,'fully_verified':0,'offline':True,'canonical_projection_equal':True,'accepted_files_unchanged':True}))
if __name__=='__main__':
 import sys
 if sys.argv[1]=='build':build();print(OUT)
 elif sys.argv[1]=='check':check()
 else:raise SystemExit('Use build or check')
